-- PRM restaurant personnel database. SQLite. Fresh database only.
-- Source: File_Chuc_Nang_PRM_Hoan_Chinh.xlsx, Sheet1 and Actor Summary.
PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE roles (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE permissions (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, description TEXT NOT NULL);
CREATE TABLE role_permissions (role_id INTEGER NOT NULL REFERENCES roles(id), permission_id INTEGER NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, email TEXT UNIQUE COLLATE NOCASE, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id INTEGER NOT NULL REFERENCES users(id), role_id INTEGER NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE branches (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, address TEXT, latitude REAL CHECK(latitude BETWEEN -90 AND 90), longitude REAL CHECK(longitude BETWEEN -180 AND 180), geofence_radius_m INTEGER NOT NULL DEFAULT 100 CHECK(geofence_radius_m>0), require_gps INTEGER NOT NULL DEFAULT 1 CHECK(require_gps IN(0,1)), require_wifi INTEGER NOT NULL DEFAULT 1 CHECK(require_wifi IN(0,1)), require_registered_device INTEGER NOT NULL DEFAULT 1 CHECK(require_registered_device IN(0,1)), CHECK((latitude IS NULL)=(longitude IS NULL)));
CREATE TABLE branch_wifi (id INTEGER PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), ssid TEXT NOT NULL, bssid TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)), UNIQUE(branch_id,bssid));
CREATE TABLE departments (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE positions (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE employees (id INTEGER PRIMARY KEY, user_id INTEGER UNIQUE REFERENCES users(id), employee_code TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, birth_date TEXT, phone TEXT, address TEXT, branch_id INTEGER NOT NULL REFERENCES branches(id), department_id INTEGER REFERENCES departments(id), position_id INTEGER REFERENCES positions(id), manager_id INTEGER REFERENCES employees(id), hire_date TEXT NOT NULL, termination_date TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive','terminated')), CHECK(manager_id IS NULL OR manager_id<>id), CHECK(termination_date IS NULL OR termination_date>=hire_date));
CREATE TABLE employee_devices (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), device_identifier TEXT NOT NULL UNIQUE, platform TEXT, registered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at TEXT);
CREATE TABLE contracts (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), contract_number TEXT NOT NULL UNIQUE, contract_type TEXT NOT NULL CHECK(contract_type IN('probation','fixed_term','indefinite','part_time')), start_date TEXT NOT NULL, end_date TEXT, salary_basis TEXT NOT NULL CHECK(salary_basis IN('monthly','hourly')), base_salary_vnd INTEGER NOT NULL CHECK(base_salary_vnd>=0), hourly_rate_vnd INTEGER NOT NULL DEFAULT 0 CHECK(hourly_rate_vnd>=0), standard_minutes_per_month INTEGER NOT NULL DEFAULT 12480 CHECK(standard_minutes_per_month>0), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','expired','terminated')), document_url TEXT, CHECK(end_date IS NULL OR end_date>=start_date));
CREATE TABLE shift_templates (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, ends_next_day INTEGER NOT NULL DEFAULT 0 CHECK(ends_next_day IN(0,1)), break_minutes INTEGER NOT NULL DEFAULT 0 CHECK(break_minutes>=0), late_grace_minutes INTEGER NOT NULL DEFAULT 0 CHECK(late_grace_minutes>=0));
CREATE TABLE shifts (id INTEGER PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), template_id INTEGER REFERENCES shift_templates(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, required_staff INTEGER NOT NULL DEFAULT 1 CHECK(required_staff>0), status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','in_progress','closed','cancelled')), created_by INTEGER NOT NULL REFERENCES users(id), note TEXT, CHECK(ends_at>starts_at));
CREATE TABLE shift_assignments (id INTEGER PRIMARY KEY, shift_id INTEGER NOT NULL REFERENCES shifts(id), employee_id INTEGER NOT NULL REFERENCES employees(id), assigned_by INTEGER NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'assigned' CHECK(status IN('assigned','completed','cancelled')), UNIQUE(shift_id,employee_id));
CREATE TABLE attendance_events (id INTEGER PRIMARY KEY, assignment_id INTEGER NOT NULL REFERENCES shift_assignments(id), event_type TEXT NOT NULL CHECK(event_type IN('check_in','check_out')), occurred_at TEXT NOT NULL, device_id INTEGER REFERENCES employee_devices(id), latitude REAL CHECK(latitude BETWEEN -90 AND 90), longitude REAL CHECK(longitude BETWEEN -180 AND 180), gps_accuracy_m REAL CHECK(gps_accuracy_m>=0), wifi_ssid TEXT, wifi_bssid TEXT, device_valid INTEGER NOT NULL CHECK(device_valid IN(0,1)), gps_valid INTEGER NOT NULL CHECK(gps_valid IN(0,1)), wifi_valid INTEGER NOT NULL CHECK(wifi_valid IN(0,1)), result TEXT NOT NULL CHECK(result IN('accepted','rejected','pending_review')), rejection_reason TEXT, confirmed_at TEXT, CHECK((latitude IS NULL)=(longitude IS NULL)));
CREATE UNIQUE INDEX ux_attendance_accepted ON attendance_events(assignment_id,event_type) WHERE result='accepted';
CREATE TABLE attendance_records (id INTEGER PRIMARY KEY, assignment_id INTEGER NOT NULL UNIQUE REFERENCES shift_assignments(id), check_in_at TEXT, check_out_at TEXT, worked_minutes INTEGER NOT NULL DEFAULT 0 CHECK(worked_minutes>=0), overtime_minutes INTEGER NOT NULL DEFAULT 0 CHECK(overtime_minutes>=0), late_minutes INTEGER NOT NULL DEFAULT 0 CHECK(late_minutes>=0), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','present','absent','leave','adjusted')), approved_by INTEGER REFERENCES users(id), approved_at TEXT, CHECK(check_out_at IS NULL OR (check_in_at IS NOT NULL AND check_out_at>=check_in_at)), CHECK(overtime_minutes<=worked_minutes));
CREATE TABLE attendance_adjustment_requests (id INTEGER PRIMARY KEY, attendance_id INTEGER NOT NULL REFERENCES attendance_records(id), requested_by INTEGER NOT NULL REFERENCES users(id), requested_check_in TEXT, requested_check_out TEXT, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','cancelled')), reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT, review_note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(status NOT IN('approved','rejected') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)), CHECK(requested_check_out IS NULL OR requested_check_in IS NULL OR requested_check_out>=requested_check_in));
CREATE TABLE leave_types (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, is_paid INTEGER NOT NULL CHECK(is_paid IN(0,1)));
CREATE TABLE leave_balances (employee_id INTEGER NOT NULL REFERENCES employees(id), leave_type_id INTEGER NOT NULL REFERENCES leave_types(id), year INTEGER NOT NULL CHECK(year BETWEEN 2000 AND 2200), granted_minutes INTEGER NOT NULL DEFAULT 0 CHECK(granted_minutes>=0), used_minutes INTEGER NOT NULL DEFAULT 0 CHECK(used_minutes>=0), PRIMARY KEY(employee_id,leave_type_id,year));
CREATE TABLE leave_requests (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), leave_type_id INTEGER NOT NULL REFERENCES leave_types(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, requested_minutes INTEGER NOT NULL CHECK(requested_minutes>0), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','cancelled')), reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT, review_note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(ends_at>starts_at), CHECK(status NOT IN('approved','rejected') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)));
CREATE TABLE shift_swap_requests (id INTEGER PRIMARY KEY, from_assignment_id INTEGER NOT NULL REFERENCES shift_assignments(id), to_assignment_id INTEGER NOT NULL REFERENCES shift_assignments(id), requested_by INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, counterpart_status TEXT NOT NULL DEFAULT 'pending' CHECK(counterpart_status IN('pending','accepted','rejected')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','cancelled')), reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT, review_note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(from_assignment_id<>to_assignment_id), CHECK(status<>'approved' OR (counterpart_status='accepted' AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)));
CREATE TABLE payroll_periods (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','calculating','approved','paid')), approved_by INTEGER REFERENCES users(id), approved_at TEXT, CHECK(ends_on>=starts_on));
CREATE TABLE payroll_calculation_steps (id INTEGER PRIMARY KEY, period_id INTEGER NOT NULL REFERENCES payroll_periods(id), step_number INTEGER NOT NULL CHECK(step_number BETWEEN 1 AND 6), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','completed','failed')), executed_by INTEGER REFERENCES users(id), executed_at TEXT, detail TEXT, UNIQUE(period_id,step_number));
CREATE TABLE payslips (id INTEGER PRIMARY KEY, period_id INTEGER NOT NULL REFERENCES payroll_periods(id), employee_id INTEGER NOT NULL REFERENCES employees(id), contract_id INTEGER NOT NULL REFERENCES contracts(id), regular_minutes INTEGER NOT NULL DEFAULT 0 CHECK(regular_minutes>=0), overtime_minutes INTEGER NOT NULL DEFAULT 0 CHECK(overtime_minutes>=0), base_pay_vnd INTEGER NOT NULL DEFAULT 0 CHECK(base_pay_vnd>=0), overtime_pay_vnd INTEGER NOT NULL DEFAULT 0 CHECK(overtime_pay_vnd>=0), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','paid')), calculated_at TEXT, approved_by INTEGER REFERENCES users(id), approved_at TEXT, paid_at TEXT, UNIQUE(period_id,employee_id), CHECK(status='draft' OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)), CHECK(status<>'paid' OR paid_at IS NOT NULL));
CREATE TABLE payslip_items (id INTEGER PRIMARY KEY, payslip_id INTEGER NOT NULL REFERENCES payslips(id), code TEXT NOT NULL, name TEXT NOT NULL, item_type TEXT NOT NULL CHECK(item_type IN('allowance','bonus','deduction','tax','insurance')), amount_vnd INTEGER NOT NULL CHECK(amount_vnd>=0), note TEXT, UNIQUE(payslip_id,code));
CREATE TABLE star_events (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), assignment_id INTEGER REFERENCES shift_assignments(id), stars_delta INTEGER NOT NULL CHECK(stars_delta<>0), reason TEXT NOT NULL, awarded_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shift_closures (id INTEGER PRIMARY KEY, assignment_id INTEGER NOT NULL UNIQUE REFERENCES shift_assignments(id), submitted_by INTEGER NOT NULL REFERENCES users(id), note TEXT, submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','approved','rejected')), reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT, review_note TEXT, CHECK(status='submitted' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)));
CREATE TABLE shift_closure_photos (id INTEGER PRIMARY KEY, closure_id INTEGER NOT NULL REFERENCES shift_closures(id), file_url TEXT NOT NULL, captured_at TEXT NOT NULL, caption TEXT);
CREATE TABLE notifications (id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, notification_type TEXT NOT NULL, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, related_entity TEXT, related_id INTEGER);
CREATE TABLE notification_recipients (notification_id INTEGER NOT NULL REFERENCES notifications(id), user_id INTEGER NOT NULL REFERENCES users(id), read_at TEXT, PRIMARY KEY(notification_id,user_id));
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY, actor_user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_employee_department ON employees(department_id,status);
CREATE INDEX ix_shift_schedule ON shifts(branch_id,starts_at,status);
CREATE INDEX ix_assignment_employee ON shift_assignments(employee_id,status);
CREATE INDEX ix_attendance_events ON attendance_events(assignment_id,occurred_at);
CREATE INDEX ix_leave_employee ON leave_requests(employee_id,starts_at,status);
CREATE INDEX ix_payslip_employee ON payslips(employee_id,period_id);
CREATE INDEX ix_notification_user ON notification_recipients(user_id,read_at);
CREATE INDEX ix_star_employee ON star_events(employee_id,created_at);
CREATE INDEX ix_audit_entity ON audit_logs(entity_type,entity_id,created_at);
CREATE VIEW v_payslip_totals AS
SELECT p.*, p.base_pay_vnd+p.overtime_pay_vnd+COALESCE(i.earnings,0) AS gross_pay_vnd,
COALESCE(i.deductions,0) AS deductions_vnd,
p.base_pay_vnd+p.overtime_pay_vnd+COALESCE(i.earnings,0)-COALESCE(i.deductions,0) AS net_pay_vnd
FROM payslips p LEFT JOIN (SELECT payslip_id,
SUM(CASE WHEN item_type IN('allowance','bonus') THEN amount_vnd ELSE 0 END) AS earnings,
SUM(CASE WHEN item_type IN('deduction','tax','insurance') THEN amount_vnd ELSE 0 END) AS deductions
FROM payslip_items GROUP BY payslip_id) i ON i.payslip_id=p.id;
CREATE VIEW v_employee_stars AS SELECT e.id AS employee_id,e.employee_code,e.full_name,COALESCE(SUM(s.stars_delta),0) AS total_stars FROM employees e LEFT JOIN star_events s ON s.employee_id=e.id GROUP BY e.id,e.employee_code,e.full_name;
CREATE VIEW v_shift_roster AS SELECT a.id AS assignment_id,s.id AS shift_id,s.branch_id,s.starts_at,s.ends_at,e.id AS employee_id,e.employee_code,e.full_name,a.status FROM shift_assignments a JOIN shifts s ON s.id=a.shift_id JOIN employees e ON e.id=a.employee_id;
CREATE VIEW v_attendance_report AS SELECT r.*,a.employee_id,s.branch_id,s.starts_at AS scheduled_start,s.ends_at AS scheduled_end FROM attendance_records r JOIN shift_assignments a ON a.id=r.assignment_id JOIN shifts s ON s.id=a.shift_id;
CREATE VIEW v_payroll_summary AS SELECT period_id,COUNT(*) AS employee_count,SUM(gross_pay_vnd) AS gross_pay_vnd,SUM(deductions_vnd) AS deductions_vnd,SUM(net_pay_vnd) AS net_pay_vnd FROM v_payslip_totals GROUP BY period_id;
PRAGMA user_version = 1;
COMMIT;
